-- Isolated local database only. All fixtures and writes roll back.
begin;
\ir progression_fixture.sql
-- A second owner on Floor 3 verifies the push reaches every eligible player.
set local role authenticated;
select set_config('request.jwt.claim.sub','c1933333-3333-4333-8333-333333333333',true);
select public.dcc_save_profile(1,'Second crawler',current_setting('dcc_test.pg_profile')::jsonb);
select public.dcc_use_crawler_profile(current_setting('dcc_test.pg_game')::uuid,1,(select version from public.dcc_crawler_profiles where slot=1));
reset role;
update public.dcc_crawlers set dungeon_floor=3 where owner_user_id='c1933333-3333-4333-8333-333333333333'and campaign_id=current_setting('dcc_test.pg_game')::uuid;
create function pg_temp.menu(op text,payload jsonb)returns jsonb language plpgsql as $$begin return public.dcc_selection_menu_action(current_setting('dcc_test.pg_game')::uuid,op,payload);end$$;
create function pg_temp.menu_crawler(op text,payload jsonb)returns jsonb language plpgsql as $$begin return pg_temp.menu(op,jsonb_build_object('crawlerId',current_setting('dcc_test.pg_id'),'version',(select version from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid))||payload);end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select pg_temp.pg_error('select pg_temp.menu(''push'',''{"floor":3}'')','42501');
select pg_temp.pg_error('select pg_temp.menu(''draft'',''{}'')','42501');
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.menu('close','{"floor":3}');
select pg_temp.pg_error('select pg_temp.menu(''push'',''{"floor":4}'')','22023');
select pg_temp.pg_act('offer','{"offers":[{"raceId":"human","classId":"blizzardmancer","waivers":[]}]}');
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select pg_temp.pg_error('select pg_temp.pg_act(''select'',jsonb_build_object(''offerId'',(select progression#>>''{offers,0,id}''from public.dcc_crawlers where id=current_setting(''dcc_test.pg_id'')::uuid),''choices'',''{}''::jsonb,''split'',''{}''::jsonb,''skip'',''[]''::jsonb))','22023');
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select set_config('dcc_test.menu_before',(select (to_jsonb(c)-'selection_menus'-'version')::text from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),true);
select pg_temp.pg_assert(pg_temp.menu('push','{"floor":3}')->>'pushed'='2','Did not push Floor 3 to both players.');
select pg_temp.pg_assert((select to_jsonb(c)-'selection_menus'-'version'=current_setting('dcc_test.menu_before')::jsonb from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),'Push modified existing crawler benefits.');
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select pg_temp.pg_act('select',jsonb_build_object('offerId',(select progression#>>'{offers,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'choices','{}'::jsonb,'split','{}'::jsonb,'skip','[]'::jsonb));
select pg_temp.pg_assert((select selection_menus#>>'{deliveries,0,status}'='completed'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'Floor 3 delivery did not complete.');
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.pg_assert(pg_temp.menu('push','{"floor":3}')->>'pushed'='1','Completed crawler was not skipped while delivering to the other player.');
reset role;
update public.dcc_crawlers set dungeon_floor=6 where id=current_setting('dcc_test.pg_id')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.pg_assert(pg_temp.menu('push','{"floor":6}')->>'pushed'='0','Specialization pushed without reviewed options.');
select pg_temp.menu_crawler('draft','{"floor":6,"options":[{"name":"Frost Warden","benefits":"GM reviewed: protects the party. Existing ranks already include this benefit."},{"name":"Winter Scholar","benefits":"GM reviewed lore specialization; benefits resolved manually."}]}');
select pg_temp.pg_assert(pg_temp.menu('push','{"floor":6}')->>'pushed'='1','Specialization push failed.');
select set_config('dcc_test.delivery',(select selection_menus#>>'{deliveries,1,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),true);
select set_config('dcc_test.choice',(select selection_menus#>>'{deliveries,1,options,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),true);
select set_config('request.jwt.claim.sub','c1933333-3333-4333-8333-333333333333',true);
select pg_temp.pg_error('select pg_temp.menu_crawler(''choose'',jsonb_build_object(''deliveryId'',current_setting(''dcc_test.delivery''),''choiceId'',current_setting(''dcc_test.choice''),''confirmed'',true))','42501');
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select pg_temp.pg_error('select pg_temp.menu_crawler(''choose'',jsonb_build_object(''deliveryId'',current_setting(''dcc_test.delivery''),''choiceId'',''00000000-0000-4000-8000-000000000000'',''confirmed'',true))','22023');
select set_config('dcc_test.menu_before',(select (to_jsonb(c)-'selection_menus'-'version')::text from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),true);
select pg_temp.menu_crawler('choose',jsonb_build_object('deliveryId',current_setting('dcc_test.delivery'),'choiceId',current_setting('dcc_test.choice'),'confirmed',true));
select pg_temp.pg_assert((select to_jsonb(c)-'selection_menus'-'version'=current_setting('dcc_test.menu_before')::jsonb from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),'Specialization replayed old benefits or refilled resources.');
select pg_temp.pg_error('select pg_temp.menu_crawler(''choose'',jsonb_build_object(''deliveryId'',current_setting(''dcc_test.delivery''),''choiceId'',current_setting(''dcc_test.choice''),''confirmed'',true))','22023');
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.pg_error('select pg_temp.menu_crawler(''draft'',''{"floor":6,"options":[{"name":"Replacement","benefits":"Already complete"}]}'')','22023');
reset role;
update public.dcc_crawlers set dungeon_floor=9 where id=current_setting('dcc_test.pg_id')::uuid;
set local role authenticated;
select pg_temp.menu_crawler('draft','{"floor":9,"options":[{"name":"Ice Regent","benefits":"GM-reviewed Floor 9 option"}]}');
select pg_temp.menu('push','{"floor":9}');
select set_config('dcc_test.delivery',(select selection_menus#>>'{deliveries,2,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),true);
select set_config('dcc_test.choice',(select selection_menus#>>'{deliveries,2,options,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),true);
select pg_temp.menu('close','{"floor":9}');
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select pg_temp.pg_error('select pg_temp.menu_crawler(''choose'',jsonb_build_object(''deliveryId'',current_setting(''dcc_test.delivery''),''choiceId'',current_setting(''dcc_test.choice''),''confirmed'',true))','22023');
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.menu('push','{"floor":9}');
reset role;
update public.dcc_crawlers set dungeon_floor=10 where id=current_setting('dcc_test.pg_id')::uuid;
select pg_temp.pg_assert((select selection_menus#>>'{deliveries,2,status}'='closed'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'Floor change did not close the pending menu.');
select pg_temp.pg_assert(not has_function_privilege('authenticated','dcc_private.progression_019(uuid,uuid,text,jsonb)','EXECUTE')and not has_function_privilege('anon','public.dcc_selection_menu_action(uuid,text,jsonb)','EXECUTE'),'Menu bypass permissions are too broad.');
update public.dcc_crawlers set dungeon_floor=12 where id=current_setting('dcc_test.pg_id')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.menu_crawler('draft','{"floor":12,"options":[{"name":"Winter Sovereign","benefits":"GM-reviewed Floor 12 option"}]}');
select pg_temp.pg_assert(pg_temp.menu('push','{"floor":12}')->>'pushed'='1','Floor 12 menu unavailable.');
reset role;
select 'PASS: GM delivery gates, original benefit preservation, private choices, immutable milestones, withdrawal and floor-change expiry' as result;
rollback;

-- A pushed catalog needs no separate per-player offer preparation.
begin;
\ir progression_fixture.sql
set local role authenticated;
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select set_config('dcc_test.catalog_before',(select to_jsonb(c)::text from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),true);
select pg_temp.pg_error('select pg_temp.pg_act(''catalog-select'',''{"raceId":"cat","classId":"fighter","choices":{},"split":{},"skip":[]}'')','22023');
select pg_temp.pg_assert((select to_jsonb(c)=current_setting('dcc_test.catalog_before')::jsonb from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),'Failed catalog choice left an internal offer or changed crawler data.');
select pg_temp.pg_act('catalog-select','{"raceId":"human","classId":"blizzardmancer","choices":{},"split":{},"skip":[],"waivers":["selection-rank-cap"]}');
select pg_temp.pg_assert((select third_floor#>>'{selected,raceId}'='human'and progression#>'{selection,waivers}'='[]'::jsonb and selection_menus#>>'{deliveries,0,status}'='completed'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'Catalog selection bypassed review constraints or failed to complete.');
select pg_temp.pg_error('select pg_temp.pg_act(''catalog-select'',''{"raceId":"human","classId":"blizzardmancer","choices":{},"split":{},"skip":[]}'')','22023');
select 'PASS: catalog authorization, atomic legal selection, forged waiver rejection and once-only completion' as result;
rollback;
